@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{--bg:#0b1421;--panel:#111d2c;--panel2:#142234;--panel3:#18283a;--line:#25364a;--muted:#91a1b5;--soft:#c3ceda;--text:#f2f5f8;--gold:#e4b85c;--gold2:#f1d28c;--green:#57c7a0;--red:#ed7d78;--blue:#77a9ee;--shadow:0 12px 32px rgba(0,0,0,.2)}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px 'DM Sans',sans-serif;min-height:100vh}button,input,select{font:inherit}button{cursor:pointer;color:inherit}#app{min-height:100vh}.shell{min-height:100vh;display:flex}.sidebar{width:238px;background:#0d1826;border-right:1px solid #1f2c3d;display:flex;flex-direction:column;padding:23px 14px 16px;flex-shrink:0;position:fixed;inset:0 auto 0 0;z-index:5}.brand{display:flex;align-items:center;gap:12px;padding:2px 10px 24px}.brand-mark{height:36px;width:36px;display:grid;place-items:center;background:linear-gradient(145deg,#eacb82,#bd8f3e);color:#18202a;border-radius:10px;font:800 18px Manrope;box-shadow:0 4px 16px #b58b3e33}.brand-name{font:800 18px Manrope;letter-spacing:1.6px}.brand-sub{font-size:9px;color:#8b9caf;letter-spacing:1.7px;margin-top:1px}.nav-label{font-size:9px;letter-spacing:1.5px;color:#6e8094;padding:9px 12px 7px;text-transform:uppercase}.nav{display:grid;gap:4px}.nav button{height:40px;border:0;background:transparent;color:#9eacbd;border-radius:8px;display:flex;align-items:center;gap:12px;text-align:left;padding:0 12px;font-size:12px;font-weight:600;transition:.18s}.nav button .ico{width:18px;text-align:center;color:#8395a9;font-size:15px}.nav button:hover{background:#162538;color:#fff}.nav button.active{background:#1b2b3c;color:#f3d48f;box-shadow:inset 2px 0 #e4b85c}.nav button.active .ico{color:var(--gold)}.side-spacer{flex:1}.side-country{border:1px solid var(--line);border-radius:10px;padding:12px;margin:12px 3px 14px;background:#111e2c}.side-country .flag{font-size:20px;margin-right:8px}.country-row{display:flex;align-items:center}.side-country strong{font:700 12px Manrope}.side-country small{display:block;color:var(--muted);font-size:10px;margin:7px 0 0 32px}.side-footer{border-top:1px solid #213145;padding:14px 8px 0;color:#77899d;font-size:10px;display:flex;align-items:center;justify-content:space-between}.status-dot{height:7px;width:7px;border-radius:50%;background:var(--green);display:inline-block;margin-right:6px;box-shadow:0 0 8px #57c7a077}
.main{margin-left:238px;width:calc(100% - 238px);min-width:0}.topbar{height:69px;border-bottom:1px solid #1d2b3c;display:flex;align-items:center;justify-content:space-between;padding:0 32px;background:#0c1624;position:sticky;top:0;z-index:4}.crumb{color:#7f91a5;font-size:11px}.crumb b{color:#f3f5f7;font-weight:600}.top-actions{display:flex;align-items:center;gap:10px}.date-chip,.speed-control{border:1px solid var(--line);background:#111d2b;border-radius:7px;padding:7px 10px;color:#adbac8;font-size:10px}.date-chip{display:flex;align-items:center;gap:8px}.date-chip b{color:#f4d692;font-weight:700}.speed-control{display:flex;padding:3px;gap:2px}.speed-control button{border:0;background:transparent;color:#8998a9;border-radius:5px;padding:5px 8px;font-size:10px}.speed-control button.selected{background:#27384a;color:#f2d18a}.icon-btn{position:relative;width:33px;height:33px;border:1px solid var(--line);background:#111d2b;border-radius:7px;color:#bdc7d3}.notif-dot{position:absolute;height:6px;width:6px;background:var(--red);border-radius:50%;right:6px;top:6px;border:1px solid #101c29}.avatar{width:32px;height:32px;border-radius:50%;display:grid;place-items:center;background:#39485b;border:1px solid #68788c;color:#f0d087;font-weight:700;font-size:11px;margin-left:4px}.content{max-width:1450px;margin:0 auto;padding:27px 32px 42px}.page-head{display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:20px}.eyebrow{font-size:9px;text-transform:uppercase;letter-spacing:1.7px;color:var(--gold);font-weight:700;margin-bottom:7px}.page-head h1{font:800 24px Manrope;margin:0;letter-spacing:-.7px}.page-head p{margin:6px 0 0;color:var(--muted);font-size:12px}.btn{border:1px solid var(--line);background:#18283a;border-radius:7px;padding:9px 13px;color:#d9e0e8;font-size:11px;font-weight:700;transition:.15s}.btn:hover{border-color:#53657a;background:#203349}.btn.gold{background:var(--gold);color:#1c2530;border-color:var(--gold);box-shadow:0 4px 14px #c99d4e22}.btn.gold:hover{background:var(--gold2)}.btn.ghost{background:transparent}.btn.small{padding:7px 10px;font-size:10px}.btn.danger{color:#f29c92;border-color:#603d45;background:#2c2029}.grid{display:grid;gap:14px}.stats-grid{grid-template-columns:repeat(4,minmax(0,1fr));margin-bottom:14px}.card{background:var(--panel);border:1px solid var(--line);border-radius:10px;box-shadow:var(--shadow);min-width:0}.stat-card{padding:15px 16px 13px;position:relative;overflow:hidden}.stat-head{display:flex;justify-content:space-between;align-items:center;color:#98a8bb;font-size:10px}.stat-icon{height:27px;width:27px;border-radius:7px;display:grid;place-items:center;background:#1a2a3c;color:var(--gold);font-size:14px}.stat-value{font:800 22px Manrope;letter-spacing:-.5px;margin:9px 0 2px}.stat-foot{font-size:10px;color:#8495a8}.trend{color:var(--green);font-size:10px;margin-left:5px}.trend.negative{color:var(--red)}.spark{position:absolute;right:13px;bottom:15px;opacity:.8}.dashboard-grid{grid-template-columns:minmax(0,1.7fr) minmax(270px,.9fr);align-items:start}.card-head{padding:15px 17px 12px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #243448}.card-title{font:700 12px Manrope;letter-spacing:.1px}.card-sub{color:#8192a5;font-size:10px;margin-top:4px}.chart-card{padding-bottom:10px}.chart-legend{display:flex;align-items:center;gap:14px;color:#8e9db0;font-size:9px}.legend-dot{height:6px;width:6px;display:inline-block;border-radius:50%;margin-right:5px;background:var(--gold)}.legend-dot.blue{background:#75a7e7}.chart-wrap{padding:10px 12px 0;height:204px}.chart-wrap svg{width:100%;height:100%;overflow:visible}.chart-label{fill:#73859a;font:9px 'DM Sans'}.chart-grid{stroke:#243347;stroke-width:1}.chart-tooltip{fill:#dce4ec;font:9px 'DM Sans'}.lower-grid{grid-template-columns:1.1fr 1fr 1fr;margin-top:14px}.panel-body{padding:13px 16px}.news-item{display:flex;gap:10px;padding:10px 0;border-bottom:1px solid #223145}.news-item:last-child{border:0}.news-icon{flex:0 0 28px;height:28px;border-radius:7px;background:#202d3b;display:grid;place-items:center;color:var(--gold)}.news-copy{min-width:0}.news-copy strong{font-size:10px;display:block;font-weight:600;line-height:1.45}.news-copy small{color:#8393a6;font-size:9px;display:block;margin-top:4px}.tag{display:inline-flex;align-items:center;border:1px solid #35485e;border-radius:20px;padding:3px 7px;color:#9cadbf;font-size:9px;white-space:nowrap}.tag.gold{color:#e8c879;border-color:#665634;background:#29271f}.tag.green{color:#79d4b0;border-color:#315c51;background:#192a2d}.tag.red{color:#f09389;border-color:#64404a;background:#2e202a}.bar-row{display:grid;grid-template-columns:90px 1fr 28px;gap:9px;align-items:center;margin:12px 0}.bar-label{font-size:10px;color:#aab7c6}.bar-track{height:6px;border-radius:8px;background:#223246;overflow:hidden}.bar-fill{height:100%;background:var(--gold);border-radius:8px}.bar-value{font-size:9px;color:#aab8c7;text-align:right}.event-card{padding:15px 16px;border-color:#4c422f;background:linear-gradient(135deg,#1d2730,#171f2a)}.event-kicker{display:flex;align-items:center;justify-content:space-between;color:#e3c476;font-size:9px;text-transform:uppercase;letter-spacing:1.2px;font-weight:700}.event-card h3{font:700 13px Manrope;margin:11px 0 6px}.event-card p{color:#9eacbc;font-size:10px;line-height:1.6;margin:0 0 13px}.event-card .btn{width:100%}.section-title{font:700 12px Manrope}.muted{color:var(--muted)}

