/* management screens */
.two-col{grid-template-columns:minmax(0,1.45fr) minmax(270px,.8fr);align-items:start}.three-col{grid-template-columns:repeat(3,minmax(0,1fr))}.metric-row{display:flex;gap:12px;flex-wrap:wrap}.mini-metric{flex:1;min-width:120px;padding:13px;border:1px solid #293a4f;background:#142234;border-radius:8px}.mini-metric label{display:block;color:#90a0b2;font-size:9px}.mini-metric strong{display:block;font:700 18px Manrope;margin-top:8px}.mini-metric small{color:#7e91a6;font-size:9px}.control-row{padding:14px 0;border-bottom:1px solid #233348}.control-row:last-child{border:0}.control-top{display:flex;justify-content:space-between;align-items:center;margin-bottom:9px}.control-top label{font-size:11px;color:#d4dce5;font-weight:600}.control-top output{font:700 11px Manrope;color:var(--gold)}input[type=range]{width:100%;accent-color:var(--gold);height:4px;cursor:pointer}.hint{font-size:9px;color:#8292a5;margin-top:5px;line-height:1.45}.select{background:#152437;border:1px solid #33455a;color:#e4e9ef;border-radius:6px;padding:7px 9px;font-size:10px;max-width:170px}.table{width:100%;border-collapse:collapse}.table th{text-align:left;color:#8092a7;font-size:9px;text-transform:uppercase;letter-spacing:.7px;padding:10px 8px;border-bottom:1px solid #29394c}.table td{padding:11px 8px;border-bottom:1px solid #223145;font-size:10px;color:#c5cfdb;vertical-align:middle}.table tr:last-child td{border:0}.person{display:flex;align-items:center;gap:8px}.person-avatar{height:28px;width:28px;border-radius:7px;background:#29384a;display:grid;place-items:center;color:#e7c77b;font-size:10px;font-weight:700}.person strong{display:block;color:#e4e9ef;font-size:10px}.person small{display:block;color:#8797aa;font-size:9px;margin-top:3px}.country-card{padding:15px;position:relative}.country-card:hover{border-color:#506078}.country-top{display:flex;align-items:center;gap:10px}.country-flag{font-size:22px}.country-name{font:700 12px Manrope}.country-meta{font-size:9px;color:#8798aa;margin-top:3px}.country-stats{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin:14px 0}.country-stats div{padding:8px;background:#142335;border-radius:6px}.country-stats small{display:block;color:#8293a7;font-size:8px}.country-stats b{display:block;font:700 11px Manrope;margin-top:4px}.country-actions{display:flex;gap:6px;flex-wrap:wrap}.country-actions .btn{flex:1;white-space:nowrap}.project{padding:14px 0;border-bottom:1px solid #27374a}.project:last-child{border:0}.project-line{display:flex;justify-content:space-between;align-items:center}.project-name{font-size:11px;font-weight:700}.project-desc{font-size:9px;color:#8999ac;margin:5px 0 9px;line-height:1.5}.progress{height:5px;background:#26364a;border-radius:8px;overflow:hidden}.progress span{height:100%;background:var(--gold);display:block;border-radius:8px}.notice{border:1px solid #33465a;background:#172638;border-radius:7px;padding:11px 12px;color:#aab8c7;font-size:10px;line-height:1.55}.notice strong{color:#ebd18e}.notice.warn{border-color:#68513a;background:#28251f}.notice.danger{border-color:#663f49;background:#2c2029}.pill-row{display:flex;gap:7px;flex-wrap:wrap;margin-top:10px}.map-card{height:286px;background:radial-gradient(ellipse at 50% 54%,#263d4c 0,#172d3a 33%,#102130 70%);position:relative;overflow:hidden;border-radius:8px}.map-card:before{content:'';position:absolute;inset:0;background-image:linear-gradient(32deg,transparent 48%,#68838b13 49%,transparent 50%),linear-gradient(148deg,transparent 47%,#68838b12 48%,transparent 49%);background-size:140px 110px,180px 130px}.map-land{position:absolute;background:#344a4c;border:1px solid #68786688;box-shadow:0 12px 30px #0005;opacity:.82}.land-a{width:35%;height:43%;top:23%;left:29%;border-radius:51% 42% 60% 35%;transform:rotate(-14deg)}.land-b{width:25%;height:28%;top:14%;left:65%;border-radius:40% 60% 55% 40%;transform:rotate(23deg)}.land-c{width:28%;height:29%;top:58%;left:8%;border-radius:60% 40% 48% 55%;transform:rotate(9deg)}.map-label{position:absolute;font-size:9px;color:#c0c6b5;text-shadow:0 1px 5px #000}.map-center{position:absolute;left:46%;top:40%;height:12px;width:12px;border-radius:50%;background:#e5b951;box-shadow:0 0 0 5px #e5b95133,0 0 15px #e5b951;z-index:2}.map-country{position:absolute;left:49%;top:44%;font-size:8px;color:#f0d283;text-shadow:0 1px 4px #000;z-index:3}.modal-backdrop{position:fixed;inset:0;background:#050a11c9;backdrop-filter:blur(4px);display:grid;place-items:center;z-index:20;padding:18px}.modal{width:min(510px,100%);background:#142131;border:1px solid #526076;border-radius:12px;box-shadow:0 26px 90px #0009;overflow:hidden}.modal-head{padding:18px 20px;border-bottom:1px solid #304155;display:flex;justify-content:space-between;align-items:center}.modal-kicker{color:var(--gold);font-size:9px;text-transform:uppercase;letter-spacing:1.4px;font-weight:700}.modal-head h2{font:800 17px Manrope;margin:6px 0 0}.modal-body{padding:18px 20px;color:#acb9c8;font-size:11px;line-height:1.65}.choice{width:100%;text-align:left;background:#1a2a3c;border:1px solid #32465c;padding:12px;border-radius:8px;margin-top:8px;transition:.15s}.choice:hover{border-color:#c49c50;background:#223246}.choice strong{display:block;color:#f1d38f;font-size:11px}.choice span{display:block;color:#9daaba;font-size:10px;margin-top:4px}.modal-close{background:transparent;border:0;color:#91a1b5;font-size:20px}.modal-footer{border-top:1px solid #304155;padding:12px 20px;display:flex;justify-content:space-between;align-items:center;color:#7f91a5;font-size:9px}.toast{position:fixed;bottom:22px;right:22px;z-index:30;background:#25394b;border:1px solid #4d6278;color:#eff4f7;padding:11px 15px;border-radius:8px;font-size:11px;box-shadow:var(--shadow);opacity:0;transform:translateY(12px);transition:.25s;pointer-events:none}.toast.show{opacity:1;transform:translateY(0)}.mobile-menu{display:none}
@media(max-width:1050px){.sidebar{width:205px}.main{margin-left:205px;width:calc(100% - 205px)}.content{padding:24px 22px}.topbar{padding:0 22px}.stats-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.lower-grid{grid-template-columns:1fr 1fr}.dashboard-grid{grid-template-columns:minmax(0,1.4fr) minmax(240px,.8fr)}}
@media(max-width:760px){.sidebar{width:68px;padding:16px 8px}.brand{justify-content:center;padding:2px 0 22px}.brand-name,.brand-sub,.nav-label,.nav button .label,.side-country,.side-footer{display:none}.nav button{justify-content:center;padding:0;gap:0}.nav button .ico{font-size:17px}.main{margin-left:68px;width:calc(100% - 68px)}.topbar{height:60px;padding:0 13px}.content{padding:20px 14px 34px}.top-actions{gap:6px}.date-chip{font-size:9px;padding:7px}.speed-control button{padding:5px 6px;font-size:9px}.avatar{display:none}.dashboard-grid,.two-col{grid-template-columns:1fr}.lower-grid{grid-template-columns:1fr}.three-col{grid-template-columns:1fr 1fr}.page-head h1{font-size:21px}.page-head p{font-size:10px}.map-card{height:240px}}
@media(max-width:480px){.stats-grid{gap:8px}.stat-card{padding:12px}.stat-value{font-size:19px}.chart-wrap{height:175px}.three-col{grid-template-columns:1fr}.date-chip span:first-child{display:none}.page-head{align-items:flex-start;gap:10px}.page-head>.btn{padding:8px;font-size:9px}.content{padding-left:11px;padding-right:11px}.table th,.table td{padding:8px 5px}.table{font-size:9px}}

