ion</span><div class="bar-track"><div class="bar-fill" style="width:${clamp(state.inflation*8)}%;background:${state.inflation>5?'var(--red)':'var(--blue)'}"></div></div><span class="bar-value">${num(state.inflation)}%</span></div><div class="bar-row"><span class="bar-label">Unemployment</span><div class="bar-track"><div class="bar-fill" style="width:${clamp(state.unemployment*7)}%;background:#77a9ee"></div></div><span class="bar-value">${num(state.unemployment)}%</span></div><div class="bar-row"><span class="bar-label">Corruption</span><div class="bar-track"><div class="bar-fill" style="width:${clamp(state.corruption)}%;background:${state.corruption>45?'var(--red)':'var(--gold)'}"></div></div><span class="bar-value">${Math.round(state.corruption)}</span></div><div class="hint">Indicators update as policy takes effect.</div></div></div><div class="card">${cardHead('Cabinet brief','Latest from your ministers')}<div class="panel-body">${(state.news.slice(0,2).length?state.news.slice(0,2):[{title:'The morning brief is ready',detail:'Review national indicators and set the priorities for your first month.',type:'Briefing'}]).map(n=>`<div class="news-item"><div class="news-icon">◈</div><div class="news-copy"><strong>${n.title}</strong><small>${n.type} · ${n.date||'Today'}</small></div></div>`).join('')}</div></div></div></div><div class="grid" style="grid-template-columns:1.55fr 1fr;margin-top:14px"><div class="card">${cardHead('International outlook','Regional partners and strategic competitors',`<button class="btn small ghost" onclick="navigate('diplomacy')">Open diplomacy →</button>`)}<div class="panel-body" style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px">${state.countries.slice(0,3).map(c=>`<div class="mini-metric"><label>${c.flag} ${c.name}</label><strong>${c.relation>60?'Warm':c.relation>35?'Stable':'Tense'}</strong><small>Trade ₡${c.trade}B · ${c.stance}</small></div>`).join('')}</div></div><div class="card event-card"><div class="event-kicker"><span>◉ Presidential decision</span><span class="tag gold">${state.activeEvent?state.activeEvent.type:'Next briefing'}</span></div><h3>${state.activeEvent?state.activeEvent.title:'Your next decision is waiting'}</h3><p>${state.activeEvent?state.activeEvent.text:'Advance the calendar to see the next report from your ministers, intelligence service, or foreign office.'}</p><button class="btn gold" onclick="${state.activeEvent?'openEvent()':'advance()'}">${state.activeEvent?'Review report':'Advance to next month'} →</button></div></div>${alerts?`<div class="notice warn" style="margin-top:14px"><strong>⚠ Attention required.</strong> ${state.coalition<40?'Coalition support is fragile. ':' '}${state.stability<45?'National stability is under strain. ':' '}${state.treasury<10?'Treasury reserves are low.':''}</div>`:''}`}
