e.countries.map(c=>`<div class="card country-card"><div class="country-top"><span class="country-flag">${c.flag}</span><div><div class="country-name">${c.name}</div><div class="country-meta">${c.system} · ${c.stance}</div></div></div><div class="country-stats"><div><small>HEAD OF STATE</small><b>${c.leader}</b></div><div><small>ECONOMY</small><b>₡${c.gdp.toFixed(0)}B GDP</b></div><div><small>BILATERAL TIES</small><b>${Math.round(c.relation)}/100</b></div><div><small>TRADE</small><b>₡${c.trade.toFixed(0)}B / yr</b></div></div><div class="country-meta">Resources: ${c.resources.join(' · ')}<br>Strategic interest: ${c.interest}</div><div class="bar-track" style="margin:9px 0 11px"><div class="bar-fill" style="width:${clamp(c.relation)}%;background:${c.relation<30?'var(--red)':'var(--gold)'}"></div></div><div class="country-actions"><button class="btn small" onclick="countryAction('${c.id}','trade')">Trade deal</button><button class="btn small" onclick="countryAction('${c.id}','treaty')">Propose treaty</button><button class="btn small ghost" onclick="countryAction('${c.id}','sanction')">Sanction</button></div></div>`).join('')}</div>`}
