 function advance(automatic=false){if(state.activeEvent&&!automatic){openEvent();return}if(state.gameOver)return;if(!automatic&&state.activeEvent)state.activeEvent=null;const total=Object.values(state.budget).reduce((a,b)=>a+b,0),rev=state.gdp*state.tax/1200,spend=state.gdp*total/1200,delta=rev-spend;state.treasury+=delta;state.debt-=delta;if(state.treasury<0){state.debt+=Math.abs(Math.min(0,state.treasury))*.12}const infraBonus=(state.infrastructure-50)*.004,educationBonus=(state.education-50)*.003,tradeBonus=state.countries.reduce((a,c)=>a+c.trade,0)*.0004;let policyBonus=state.policy==='Public investment'?.12:state.policy==='Industrial renewal'?.1:state.policy==='Austerity'?-.08:0;state.growth=clamp(state.growth+infraBonus+educationBonus+tradeBonus+policyBonus-(state.inflation>6?.12:0),-1.5,1.8);state.gdp*=1+state.growth/100;state.inflation=clamp(state.inflation+(state.tax>30?.08:0)-(state.budget.health+state.budget.welfare>40?.04:0)+(state.growth>.8?.06:0),.2,15);state.unemployment=clamp(state.unemployment-(state.growth>.35?.12:-.05)+(state.inflation>7?.08:0),2,25);state.readiness=clamp(state.readiness+(state.budget.defence-18)*.035-.2);state.army=clamp(state.army+(state.budget.defence-18)*.018-.08);state.air=clamp(state.air+(state.budget.defence-18)*.015-.1);state.navy=clamp(state.navy+(state.budget.defence-18)*.014-.08);state.health=clamp(state.health+(state.budget.health-20)*.05-.08);state.education=clamp(state.education+(state.budget.education-17)*.045-.05);state.infrastructure=clamp(state.infrastructure+(state.budget.infrastructure-18)*.05-.06);state.stability=clamp(state.stability+(state.approval-50)*.025+(state.health-50)*.006-(state.inflation>8?.4:0));state.approval=clamp(state.approval+(state.growth>.4?.18:-.14)-(state.inflation>6?.25:0)-(state.unemployment>9?.18:0)+(state.health>60?.05:0));state.coalition=clamp(state.coalition+(state.approval>55?.06:-.12)-(state.corruption>50?.2:0));state.loyalty=clamp(state.loyalty+(state.budget.defence>=15?.08:-.15)+